rows=[('base','Base model',[32.7,32.7,29.0]),('passage','Passage only',[33.5,36.0,31.2]),('synthetic','Self-generated data',[39.7,50.6,43.4]),('gpt41','GPT-4.1 data',[46.3,59.4,49.2]),('seal','SEAL',[47.0,58.2,46.4])]
