 results.append({'id':method+'_arc','method_id':method,'metric_id':'arc','value':value,'source_id':'arc','source_location':'Table 1: '+label+' row','comparison':{'dataset':'ARC curated subset; Llama-3.2-1B-Instruct','split':'8 filtered evaluation tasks (11 training tasks)','budget':'5 independently applied self-edits per evaluation task for SEAL and self-edit baseline; method-dependent adaptation','protocol':'Section 4.1 and Table 1; percentage of edits yielding correct outputs for self-editing methods'}})
