spec={**base,'kind':'teaser','figure':{'width_in':7,'height_in':4.8,'concept_fraction':0.34,'title':'SEAL: learn how to write your own training data','geometry_source':'build_figures.py','note':'Original redesign, reported data; schematic example. Two-column draft, venue unspecified.'},'evidence':{'metrics':metrics,'results':results,'claims':claims},'charts':charts,'row_order':[r[0] for r in rows],'settings':settings,'method_labels':{m:l for m,l,v in rows},'arc_order':[r[0] for r in arc],'arc_labels':{m:l for m,l,v in arc}}
method={**base,'kind':'method','figure':{'width_in':7,'height_in':5.35,'title':'SEAL trains an editor through the results of adaptation','geometry_source':'build_figures.py'},'evidence':{'metrics':[],'results':[],'claims':[]},'method_contract':{'input':'Context C plus downstream evaluation task tau during RL training','policy':'Current LM with parameters theta_t samples candidate self-edits','inner':'Each candidate independently adapts a copy of the current weights by SFT (LoRA in the demonstrated individual updates)','evaluation':'Downstream task performance determines reward; no gradient through reward','outer':'On-policy ReST-EM: select rewarded context/edit pairs, SFT edit generation to obtain theta_(t+1)','selection':'Generic positive-improvement reward; knowledge-incorporation implementation selects the best candidate','deployment':'Generate self-edit and adapt; outer reward-training loop is not required at inference','knowledge':'Generated implications are finetuning data; downstream QA omits the source passage','fewshot':'Self-edit selects augmentations and training settings; adapted model predicts held-out output'},'canonical_geometry':'build_figures.py:method_figure'}
for name,obj in [('teaser.spec.json',spec),('method.spec.json',method),('reported-tables.json',{'source':URL,'table2':rows,'table1':arc})]: (OUT/name).write_text(json.dumps(obj,indent=2)+'\n')
